  "knowledge": "Community Influence Index (CII)",
  "description": "A composite score that measures a fan's overall influence within the community, based on their social network reach and recognized influence.",
  "definition": "CII = \\sqrt{\\text{Follower Count} \\times \\text{Content Reach}}"
}

