{
  "id": 6,
  "knowledge": "Content Creator Score (CCS)",
  "description": "Evaluates a fan's contribution as a content creator by combining the volume and quality of their user-generated content.",
  "definition": "CCS = (\u03a3 \\text{Content Submissions} + \\text{Collaborations}) \\times \\text{Average Content Quality Rating}"
}

{
  "id": 14,
  "knowledge": "Social Capital Score (SCS)",
  "description": "Represents the size and strength of a fan's social network on the platform.",
  "definition": "SCS = \\text{Social Network Size} + (\\text{Friend Connections} \\times 1.5)"
}

{
  "id": 23,
  "knowledge": "Community Influencer",
  "description": "A fan with significant social capital, characterized by a large and engaged follower base.",
  "definition": "A fan is a Community Influencer if their Follower-to-Following Ratio (FFR) is greater than 2.0 and their Community Influence Index (CII) is greater than 10000."
}

{
  "id": 5,
  "knowledge": "Follower-to-Following Ratio (FFR)",
  "description": "Measures a fan's social influence by comparing the number of users who follow them to the number of users they follow.",
  "definition": "FFR = \\frac{\\text{Follower Count}}{\\text{Following Count}}, \\text{ where Following Count is > 0}"
}
